// =====================
// Volladung Logic (Victron) — FIXED v2
// Output 1: DVCC Spannung
// Output 2: History schreiben (nur bei Volladung)
//
// Changelog v2:
// - FIX (Bug 1): Heartbeat mit bekanntem lastDVCC gibt nur den
//   gecachten Wert erneut aus und läuft NICHT mehr durch die
//   reguläre Detektionslogik (deltaVal/lastMaxCVL/History-Write).
//   Vorher konnte ein zwischen "fällig" und "echtem CVL-Abfall"
//   eintreffender Heartbeat mit veraltetem lastCVL fälschlich
//   fullChargeDetected auslösen und kwDiff vorzeitig auf 0 setzen.
// - NEU: Fail-safe-Timeout. Wenn DVCC=0 freigegeben wurde
//   (kwDiff fällig), aber nach FAILSAFE_HOURS kein echter
//   CVL-Abfall erkannt wurde, wird hart auf FLOAT_VOLTAGE
//   zurückgefallen + node.warn(), damit kein Fehltrigger
//   unbegrenzt offen bleibt.
// - NEU: node.warn() bei jedem fullChargeDetected und beim
//   undefined-Fallback von lastMaxCVL, zur besseren
//   Nachvollziehbarkeit im Node-RED-Log.
// =====================

// ----- Konfigurierbare Parameter -----

var DELTA_V = 0.5;
var FLOAT_VOLTAGE = 53.9;
var FULL_CHARGE_INTERVAL_WEEKS = 2;  // 1 = wöchentlich, 2 = alle 2 Wochen, usw.
var FAILSAFE_HOURS = 40;             // Fail-safe: nach X Stunden ungetriggert -> zwangsweise abschließen

function getKW(date) {
    var d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
    var dayNum = d.getUTCDay() || 7;
    d.setUTCDate(d.getUTCDate() + 4 - dayNum);
    var yearStart = new Date(Date.UTC(d.getUTCFullYear(),0,1));
    return Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
}

function weeksDiff(kwA, yearA, kwB, yearB) {
    if (yearA === yearB) return kwB - kwA;
    var lastKWofYearA = getKW(new Date(Date.UTC(yearA, 11, 28)));
    return (lastKWofYearA - kwA) + kwB;
}

function hhmm(d) {
    var h = ('0'+d.getHours()).slice(-2);
    var m = ('0'+d.getMinutes()).slice(-2);
    var s = ('0'+d.getSeconds()).slice(-2);
    return h+':'+m+':'+s;
}

var now = new Date();
var currentKW = getKW(now);
var currentYear = now.getFullYear();
var currentDateStr = now.toISOString().slice(0,10);
var nowTimeStr = hhmm(now);

// ----- Guard: History muss geladen sein -----
if (!flow.get('volladung_history_ready')) {
    node.status({ fill: 'yellow', shape: 'ring',
        text: '⏳ warte auf History... | ' + nowTimeStr });
    return null;
}

// ----- Heartbeat: reine Re-Evaluation, KEINE Detektionslogik -----
// FIX Bug 1: gibt bei bekanntem lastDVCC nur den gecachten Wert aus,
// läuft nicht mehr durch die reguläre CVL-Verarbeitung weiter.
if (msg.topic === "heartbeat") {
    var lastDVCC = context.get('lastDVCC');

    if (typeof lastDVCC === "number") {
        // Fail-safe-Check: falls seit Freigabe zu lange nichts erkannt wurde
        var releaseStart = context.get('releaseStart');
        if (lastDVCC === 0 && releaseStart) {
            var hoursSinceRelease = (now.getTime() - releaseStart) / 3600000;
            if (hoursSinceRelease > FAILSAFE_HOURS) {
                node.warn('Volladung-Timeout: CVL-Abfall seit ' +
                    hoursSinceRelease.toFixed(1) + 'h nicht erkannt, erzwinge Reset auf Float. KW' +
                    currentKW + ' | ' + nowTimeStr);

                var history = flow.get('volladung_history') || [];
                var entry = { kw: currentKW, year: currentYear, date: currentDateStr, forced: true };
                history.push(entry);
                flow.set("volladung_history", history);

                context.set('lastMaxCVL', undefined);
                context.set('lastDVCC', FLOAT_VOLTAGE);
                context.set('releaseStart', null);

                node.status({ fill: 'red', shape: 'dot',
                    text: '⚠ FAILSAFE-RESET | KW'+currentKW+' | '+nowTimeStr });

                return [{payload: FLOAT_VOLTAGE}, {payload: JSON.stringify(history, null, 2)}];
            }
        }

        node.status({ fill: 'cyan', shape: 'dot',
            text: '⏱ HB(cached) | DVCC:'+lastDVCC+'V | '+nowTimeStr });
        return [{payload: lastDVCC}, null];
    }

    // Kein lastDVCC bekannt (z.B. nach Neustart) -> KW-only Neuberechnung
    var histHB = flow.get('volladung_history') || [];
    var lastKWHB = histHB.length > 0 ? histHB[histHB.length-1].kw : currentKW;
    var lastYearHB = histHB.length > 0 ? (histHB[histHB.length-1].year || currentYear) : currentYear;
    var lastDateHB = histHB.length > 0 ? histHB[histHB.length-1].date : currentDateStr;
    var modusHB = context.get('modus') || 'auto';

    var dvccHB;
    if (modusHB === 'manual') dvccHB = 0;
    else if (modusHB === 'bulk') dvccHB = FLOAT_VOLTAGE;
    else dvccHB = (weeksDiff(lastKWHB, lastYearHB, currentKW, currentYear) >= FULL_CHARGE_INTERVAL_WEEKS) ? 0 : FLOAT_VOLTAGE;

    context.set('lastDVCC', dvccHB);
    if (dvccHB === 0 && !context.get('releaseStart')) {
        context.set('releaseStart', now.getTime());
    }
    node.status({ fill: 'cyan', shape: 'dot',
        text: '⏱ HB(KW-only, kein Cache) | DVCC:'+dvccHB+'V | KW'+currentKW+' letzte:KW'+lastKWHB+' ('+lastDateHB+') | Intervall:'+FULL_CHARGE_INTERVAL_WEEKS+'W | '+nowTimeStr });

    return [{payload: dvccHB}, null];
}

// ----- History laden -----
var history = flow.get('volladung_history');
if (!history) history = [];

var lastEntry = history.length > 0 ? history[history.length-1] : null;
var lastFullKW = lastEntry ? lastEntry.kw : currentKW;
var lastFullYear = lastEntry ? (lastEntry.year || currentYear) : currentYear;
var lastFullDate = lastEntry ? lastEntry.date : currentDateStr;

var lastMaxCVL = context.get('lastMaxCVL');
var modus = context.get('modus');
if (!modus) modus = "auto";

var msgCount = context.get('msgCount') || 0;
var fullChargeCount = context.get('fullChargeCount') || 0;

// ----- Modus Inject -----
if (typeof msg.payload === "string") {
    if (["manual","bulk","auto"].indexOf(msg.payload) !== -1) {
        modus = msg.payload;
        context.set("modus", modus);
        context.set("lastModeChange", nowTimeStr);
        node.status({ fill:"blue", shape:"dot",
            text: "⚙ "+modus.toUpperCase()+" | KW"+currentKW+" | letzte: KW"+lastFullKW+" ("+lastFullDate+") | Intervall:"+FULL_CHARGE_INTERVAL_WEEKS+"W | "+nowTimeStr });
    }
    return null;
}

// ----- CVL Input -----
if (typeof msg.payload !== "number") return null;
var currentCVL = msg.payload;
msgCount++;
context.set('msgCount', msgCount);
context.set('lastCVL', currentCVL);
context.set('lastUpdate', nowTimeStr);

if (lastMaxCVL === undefined) {
    lastMaxCVL = currentCVL;
    node.warn('lastMaxCVL war undefined (z.B. nach Neustart), initialisiere auf currentCVL=' +
        currentCVL.toFixed(2) + 'V. Ein evtl. laufender Volladungszyklus vor diesem Punkt ' +
        'wird nicht rückwirkend erkannt.');
}

var dvccVoltage;
var fullChargeDetected = false;
var deltaVal = lastMaxCVL - currentCVL;

var kwDiff = weeksDiff(lastFullKW, lastFullYear, currentKW, currentYear);

// ----- Logik -----
if (modus === "manual") {
    dvccVoltage = 0;
}
else if (modus === "bulk") {
    dvccVoltage = FLOAT_VOLTAGE;
}
else {
    if (deltaVal >= DELTA_V) {
        if (kwDiff >= FULL_CHARGE_INTERVAL_WEEKS) {

            fullChargeDetected = true;
            fullChargeCount++;
            context.set('fullChargeCount', fullChargeCount);

            var entry = { kw: currentKW, year: currentYear, date: currentDateStr };
            history.push(entry);
            flow.set("volladung_history", history);

            node.warn('Volladung erkannt: CVL-Abfall ' + lastMaxCVL.toFixed(2) + 'V -> ' +
                currentCVL.toFixed(2) + 'V (Δ' + deltaVal.toFixed(2) + 'V) bei KW' + currentKW +
                ' (' + currentDateStr + '). History-Eintrag geschrieben.');

            lastFullKW = currentKW;
            lastFullYear = currentYear;
            lastFullDate = currentDateStr;
            kwDiff = 0;
        }
        lastMaxCVL = currentCVL;
    }

    if (currentCVL > lastMaxCVL) { lastMaxCVL = currentCVL; }

    dvccVoltage = (kwDiff >= FULL_CHARGE_INTERVAL_WEEKS) ? 0 : FLOAT_VOLTAGE;
}

context.set("lastMaxCVL", lastMaxCVL);
context.set("modus", modus);
context.set("lastDVCC", dvccVoltage);

// Fail-safe-Zeitstempel verwalten: wird gesetzt, sobald DVCC=0 freigegeben wird,
// und zurückgesetzt, sobald wieder auf Float gewechselt wird.
if (dvccVoltage === 0) {
    if (!context.get('releaseStart')) context.set('releaseStart', now.getTime());
} else {
    context.set('releaseStart', null);
}

// ----- Statusanzeige -----
var statusIcon, statusColor;
if (fullChargeDetected)       { statusIcon = "✓ VOLL";  statusColor = "green"; }
else if (modus === "manual") { statusIcon = "⚡ MAN";   statusColor = "yellow"; }
else if (modus === "bulk")   { statusIcon = "≈ BULK";  statusColor = "grey"; }
else if (dvccVoltage === 0)  { statusIcon = "↑ LADE";  statusColor = "blue"; }
else                          { statusIcon = "● FLOAT"; statusColor = "blue"; }

node.status({ fill: statusColor, shape: "dot", text:
    statusIcon+
    " | CVL:"+currentCVL.toFixed(2)+"V (max:"+lastMaxCVL.toFixed(2)+", Δ:"+deltaVal.toFixed(2)+")"+
    " | DVCC:"+dvccVoltage+"V"+
    " | KW"+currentKW+" letzte:KW"+lastFullKW+" ("+lastFullDate+") Δ"+kwDiff+"/"+FULL_CHARGE_INTERVAL_WEEKS+"W"+
    " | n="+msgCount+" full="+fullChargeCount+
    " | "+nowTimeStr });

var msgDVCC = { payload: dvccVoltage };
var msgHistory = null;
if (fullChargeDetected) {
    msgHistory = { payload: JSON.stringify(history, null, 2) };
}
return [msgDVCC, msgHistory];

var d = new Date();
var t = ('0'+d.getHours()).slice(-2)+':'+
        ('0'+d.getMinutes()).slice(-2)+':'+
        ('0'+d.getSeconds()).slice(-2);

var count = context.get('writeCount') || 0;
count++;
context.set('writeCount', count);

var v = msg.payload;
var label;
if (v === 0) label = 'DVCC=0 (BMS frei)';
else label = 'DVCC='+v+'V';

node.status({
    fill: v === 0 ? 'blue' : 'green',
    shape: 'dot',
    text: label+' | writes:'+count+' | '+t
});

return msg;

var d = new Date();
var t = ('0'+d.getHours()).slice(-2)+':'+
        ('0'+d.getMinutes()).slice(-2);

try {
    var history = JSON.parse(msg.payload);
    flow.set('volladung_history', history);
    flow.set('volladung_history_ready', true);

    var last = history.length > 0 ? history[history.length-1] : null;
    var lastText = last ? ('letzte: KW'+last.kw+' ('+last.date+')') : 'keine Einträge';

    node.status({
        fill:'green',
        shape:'dot',
        text: '✓ '+history.length+' Einträge | '+lastText+' | geladen '+t
    });
} catch (e) {
    flow.set('volladung_history', []);
    flow.set('volladung_history_ready', true);
    node.status({
        fill:'red',
        shape:'ring',
        text:'✗ History leer/ungültig | '+t
    });
}
return null;

var d = new Date();
var t = ('0'+d.getHours()).slice(-2)+':'+
        ('0'+d.getMinutes()).slice(-2)+':'+
        ('0'+d.getSeconds()).slice(-2);
var dt = d.toISOString().slice(0,10);

var count = context.get('writes') || 0;
count++;
context.set('writes', count);

node.status({
    fill:'green',
    shape:'dot',
    text: '✓ geschrieben '+dt+' '+t+' | total:'+count
});
return null;
